local config = {
  ui_story_32280401_1_dialog_content = "Akhirnya, Caelestite Terakhir tiba juga. Terima kasih sudah membuatku menunggu, sekarang coba ini!",
  ui_story_32280401_2_dialog_content = "Ada apa?",
  ui_story_32280401_3_dialog_content = "Ini benar-benar... Ah, tidak mindah itu. Cicipi saja!",
  ui_story_32280401_4_option_content = "Coba sedikit",
  ui_story_32280401_5_dialog_content = "Rasanya seperti permen lemon, tapi ada yang sedikit berbeda. Tunggu, apa mungkin...",
  ui_story_32280401_6_dialog_content = "Heheh, tampaknya The Last Caelestite memiliki selera yang cukup baik. Ini bukan permen lemon biasa!",
  ui_story_32280401_7_dialog_content = "Ini kebetulan adalah karya terbaik dari Queen Kandi, pembuat permen terhebat dalam sejarah Umbraton—<color=#FFB400>Lemon Supreme</color>!",
  ui_story_32280401_8_dialog_content = "Ada sesuatu yang sangat menyegarkan tentang ini! Saya rasa saya belum pernah makan permen sebaik ini seumur hidup saya...",
  ui_story_32280401_9_dialog_content = "Sayangnya, ini sudah tidak tersedia di pasaran lagi.",
  ui_story_32280401_10_dialog_content = "Itu karena Queen Kandi telah meninggal tiga puluh tahun yang lalu, dan dia tidak pernah membagikan resep Lemon Supreme kepada siapa pun.",
  ui_story_32280401_11_dialog_content = "Lalu itu berarti...",
  ui_story_32280401_12_dialog_content = "Yep! Ini adalah barang sekali pakai yang ditinggalkan oleh seorang prajurit perkasa dari tiga dekade yang lalu!",
  ui_story_32280401_13_dialog_content = "Seharusnya sudah basi sekarang, 'kan?",
  ui_story_32280401_14_dialog_content = "Apakah rasanya seperti sudah basi?",
  ui_story_32280401_15_dialog_content = "Tidak, tapi... Tidak apa-apa. Kenapa persisnya kamu membutuhkan bantuan saya lagi?",
  ui_story_32280401_16_dialog_content = "Pertanyaan hebat lainnya dari Caelestite Terakhir! Tepat sebelum dia meninggalkan dunia ini, Queen Kandi pernah berkata—",
  ui_story_32280401_17_dialog_content = "\"Kamu mau resepku? Bisa kok! Ada di <color=#FFB400>sana</color>! Aku meninggalkan resepku di <color=#FFB400>tempat itu</color>!\"",
  ui_story_32280401_18_dialog_content = "Kenapa terdengar seperti dia akan dieksekusi?",
  ui_story_32280401_19_dialog_content = "Dan baru-baru ini, saya telah mengkonfirmasi lokasi <color=#FFB400>tempat itu</color>! Maukah kamu datang mencarinya bersamaku?",
  ui_story_32280401_20_option_content = "Ayo kita pergi!",
  ui_story_32280401_21_dialog_content = "Saya tidak bisa bilang saya tidak tertarik untuk belajar resep rahasia permen luar biasa ini.",
  ui_story_32280401_22_dialog_content = "Itulah jenis jawaban yang saya harapkan dari Anda!",
  ui_story_32280401_23_option_content = "Hmm…",
  ui_story_32280401_24_dialog_content = "Haruskah kita benar-benar berpetualang hanya demi beberapa permen?",
  ui_story_32280401_25_dialog_content = "Kamu tahu kamu baru saja memakan Lemon Supreme terakhirku, kan? Aku tidak akan membiarkanmu pergi begitu saja setelah itu!",
  ui_story_32280401_26_dialog_content = "Jika kamu menolak untuk ikut, aku akan mengirim Conan the Enlightened, bot bom paling kuatku, langsung ke kamarmu!",
  ui_story_32280401_27_dialog_content = "Baiklah…",
  ui_story_32280401_28_dialog_content = "Tak ada waktu untuk disia-siakan! Ayo bergerak!",
  ui_story_32280401_29_dialog_content = "<color=#e8d9bb>Beberapa waktu kemudian</color>",
  ui_story_32280401_30_dialog_content = "Jadi di sinilah resep rahasia itu disembunyikan?",
  ui_story_32280401_31_dialog_content = "Ini hanya hutan biasa. Ini sangat berbeda dari yang saya bayangkan.",
  ui_story_32280401_32_dialog_content = "Seorang pejuang sejati tidak menilai musuh hanya berdasarkan penampilan saja.",
  ui_story_32280401_33_dialog_content = "Banyak orang datang mencari resep Queen Kandi, hanya untuk pergi dengan tangan hampa...",
  ui_story_32280401_34_dialog_content = "Beberapa dari mereka bahkan berubah menjadi monster selama pencarian mereka!",
  ui_story_32280401_35_dialog_content = "Itu terdengar sedikit konyol, bukan begitu?",
  ui_story_32280401_36_dialog_content = "Nah, itulah yang dikatakan oleh rumor! Anyway, kita harus melanjutkan—",
  ui_story_32280401_37_dialog_content = "Hei, apakah kamu juga mendengar suara mendengung?",
  ui_story_32280401_38_dialog_content = "Argh, mereka lagi! Monster-monster tamak yang menghisap darah itu adalah malapetaka bagi semua keberadaan!",
  ui_story_32280401_39_dialog_content = "Jangan khawatir! Sebagai prajurit yang berpengalaman, aku telah menggunakan ramuan kuat untuk mengusir mereka sebelum kita pergi!",
  ui_story_32280401_40_dialog_content = "Tapi entah kenapa, sepertinya tidak berfungsi... Bahkan, tampaknya semakin banyak nyamuk yang datang!",
  ui_story_32280401_41_dialog_content = "... Tunggu sebentar, itu bukan nyamuk... Itu lebah! Lari!",
  ui_story_32280401_42_dialog_content = "Astaga! Mengapa ada begitu banyak lebah? Dan mengapa mereka tidak berhenti mengejar kita?",
  ui_story_32280401_43_dialog_content = "Apakah kamu membawa sesuatu yang menarik mereka ke kita?",
  ui_story_32280401_44_dialog_content = "Sama sekali tidak! Saya hanya membawa barang-barang biasa saya!",
  ui_story_32280401_45_dialog_content = "Oh, oke... Tunggu, tidak! Bukan oke!",
  ui_story_32280401_46_dialog_content = "Itulah masalahnya! Kamu selalu membawa banyak permen di sakumu, dan aku yakin itulah sebabnya lebah-lebah ini tidak mau meninggalkan kita sendirian! Cepat buang itu!",
  ui_story_32280401_47_dialog_content = "Kamu ingin saya meninggalkan teman-teman baik saya? Dalam mimpimu saja! Seorang prajurit sejati tidak akan pernah melakukan sesuatu yang begitu keji!",
  ui_story_32280401_48_dialog_content = "Maka makan saja! Semuanya!",
  ui_story_32280401_49_dialog_content = "Aku tahu itu, jadi berhenti membuatku terburu-buru...",
  ui_story_32280401_50_dialog_content = "<color=#e8d9bb>Ciprat!</color>",
  ui_story_32280401_51_dialog_content = "Ke-Kenapa tiba-tiba wajahku terkena pukulan?",
  ui_story_32280401_52_dialog_content = "Ahhhh! Maaf, aku tanpa sengaja menekan cangkir jellyku terlalu keras, dan itu menyembur keluar—",
  ui_story_32280401_53_dialog_content = "<anim type=Shake><size=45><color=#e8d9bb>Buzzzzzzzz!</color></size></anim>",
  ui_story_32280401_54_dialog_content = "<color=#e8d9bb>Ketika pandangan mereka sepenuhnya terhalang oleh awan lebah yang tebal, suara dengungan marah mengisi telinga mereka...</color>",
  ui_story_32280401_55_dialog_content = "<color=#e8d9bb>Beberapa jam kemudian</color>",
  ui_story_32280401_56_dialog_content = "Nah? Apakah masih sakit?",
  ui_story_32280401_57_dialog_content = "Lebih baik tidak membicarakannya. Rasanya wajahku seperti dicabik-cabik setiap kali aku berbicara...",
  ui_story_32280401_58_dialog_content = "Yah, wajahmu memang cukup bengkak setelah semua ini...",
  ui_story_32280401_59_dialog_content = "Ohhh! Aku paham sekarang!",
  ui_story_32280401_60_dialog_content = "Orang-orang dalam rumor itu tidak pernah berubah menjadi monster! Mereka hanya berakhir seperti kamu!",
  ui_story_32280401_61_dialog_content = "Kamu benar-benar terlihat seperti platipus sekarang!",
  ui_story_32280401_62_dialog_content = "Itu benar-benar tidak membuat saya merasa lebih baik, tahu kan.",
  ui_story_32280401_63_dialog_content = "Tempat ini berbahaya... Lihat saja berapa banyak masalah yang kita hadapi hanya dalam beberapa jam!",
  ui_story_32280401_64_dialog_content = "Kami dikejar oleh lebah, tas ransel kami dicuri oleh monyet, dan ada hewan yang menggigit kepang rambutku...",
  ui_story_32280401_65_dialog_content = "Ini adalah satu bencana demi bencana lainnya...",
  ui_story_32280401_66_dialog_content = "Ya, tapi ini juga menyenangkan, 'kan? Aku belum pernah berpetualang bersama teman seperti ini sebelumnya...",
  ui_story_32280401_67_dialog_content = "Bicara untuk dirimu sendiri. Kamu bukan orang yang disengat oleh sekumpulan lebah.",
  ui_story_32280401_68_dialog_content = "Tapi setelah semua yang telah kita lalui, aku tidak peduli bahkan jika resep rahasia legendaris itu tidak ada...",
  ui_story_32280401_69_dialog_content = "Meski pada akhirnya harta karun yang sebenarnya adalah kesenangan yang kita dapatkan selama perjalanan, atau omong kosong klise lainnya...",
  ui_story_32280401_70_dialog_content = "Aku tetap akan senang!",
  ui_story_32280401_71_dialog_content = "Aku tidak tahu kamu merasa seperti itu, Zeta...",
  ui_story_32280401_72_dialog_content = "Tapi tetap saja... Saya sudah menderita terlalu banyak untuk pergi dengan tangan kosong, jadi mari kita terus mencari!",
  ui_story_32280401_73_dialog_content = "Hahahaha! Jangan khawatir, saya yakin Queen Kandi tidak akan melakukan sesuatu yang berantakan.",
  ui_story_32280401_74_dialog_content = "Benarkah? Karena menyembunyikan resepnya seperti ini tampaknya cukup kacau menurut saya.",
  ui_story_32280401_75_dialog_content = "Pokoknya... Saya pikir kita akhirnya sampai di sini.",
  ui_story_32280401_76_dialog_content = "Berdasarkan peta, resep seharusnya tersembunyi di gua di depan sana!",
  ui_story_32280401_77_dialog_content = "Serius? Sepertinya kita harus pergi melihatnya.",
  ui_story_32280401_78_dialog_content = "<color=#e8d9bb>Kedua orang itu bergegas masuk tanpa ragu sejenak dan menemukan peti tua dari kayu yang terletak di tengah gua.</color>",
  ui_story_32280401_79_dialog_content = "Lihat, sebuah peti harta karun! Resep pasti ada di dalamnya!",
  ui_story_32280401_80_dialog_content = "Tunggu sebentar! Mari pastikan tidak ada jebakan di dalamnya!",
  ui_story_32280401_81_dialog_content = "Benarkah? Setelah semua yang telah kita lalui, saya hampir berpikir kita tidak perlu terlalu berhati-hati lagi!",
  ui_story_32280401_82_dialog_content = "Nah, lihat? Aku membuka peti itu, dan tidak terjadi apa-apa!",
  ui_story_32280401_83_dialog_content = "T-Tidak bercanda, huh... Hei, ada selembar kertas di dalam peti! Apakah itu resepnya?",
  ui_story_32280401_84_dialog_content = "\"Salam, teman pencari harta karun! Selamat telah berhasil sampai sejauh ini!\"",
  ui_story_32280401_85_dialog_content = "\"Namun, saya menyesal untuk memberi tahu Anda bahwa tidak ada resep yang dapat ditemukan di sini.\"",
  ui_story_32280401_86_dialog_content = "\"Rahasia menciptakan <color=#FFB400>Lemon Supreme</color> terletak pada perjalananmu ke tempat ini.\"",
  ui_story_32280401_87_dialog_content = "... Sepertinya kamu menebaknya, Zeta.",
  ui_story_32280401_88_dialog_content = "Pokoknya, aku sudah siap secara mental untuk hasil seperti ini. Mari kita pulang saja... Uh, Zeta?",
  ui_story_32280401_89_dialog_content = "...",
  ui_story_32280401_90_dialog_content = "Apa kamu bercanda? Tipe orang apa yang benar-benar akan melanjutkan dengan akhir cerita yang klise seperti itu?",
  ui_story_32280401_91_dialog_content = "Urgh! Aku akan meledakkan gua bodoh ini menjadi puing-puing!",
  ui_story_32280401_92_dialog_content = "<color=#e8d9bb>Zeta dengan marah menendang peti dan mengeluarkan salah satu robotnya yang penuh permen.</color>",
  ui_story_32280401_93_dialog_content = "Tenanglah, Zeta!",
  ui_story_32280401_94_dialog_content = "Semoga kamu melihat ini, ratu yang curang! Inilah yang terjadi saat kamu berurusan dengan seorang prajurit!",
  ui_story_32280401_95_dialog_content = "Tunggu sebentar, Zeta... Lihat lebih dekat! Ada dasar palsu di dalam peti itu!",
  ui_story_32280401_96_dialog_content = "Dasar palsu? Hei, kamu benar! Jika saya tidak menendang peti itu tadi, kita tidak akan pernah menyadarinya!",
  ui_story_32280401_97_dialog_content = "... Apakah itu berarti catatan yang kita temukan sebelumnya hanyalah pengalihan?",
  ui_story_32280401_98_dialog_content = "Aku mengerti! Jadi begitulah cara Queen Kandi mencegah orang jahat mendapatkan resepnya.",
  ui_story_32280401_99_dialog_content = "Ini harus jadi takdir!",
  ui_story_32280401_100_dialog_content = "Ada sesuatu di bawah dasar palsu... Ini catatan lainnya!",
  ui_story_32280401_101_dialog_content = "Ini haruslah resep asli untuk <color=#FFB400>Lemon Supreme</color>, bukan?",
  ui_story_32280401_102_dialog_content = "\"Jika kamu membaca ini, berarti kamu telah menghancurkan dadaku karena kemarahan yang murni.\"",
  ui_story_32280401_103_dialog_content = "\"Mereka bilang, rasa manis paling bisa dinikmati saat dipadukan dengan rasa yang berlawanan, dan sedikit hal yang bisa membuat makanan penutup lebih manis daripada penderitaan orang lain.\"",
  ui_story_32280401_104_dialog_content = "\"Harap ketahui bahwa frustrasi Anda memberikan saya kegembiraan yang tak terkendali.\"",
  ui_story_32280401_105_dialog_content = "... Zeta?",
  ui_story_32280401_106_dialog_content = "Meledakkan.",
  ui_story_32280401_107_dialog_content = "*batuk* Astaga, Zeta... Kamu seharusnya menunggu kami keluar dulu...",
  ui_story_32280401_108_dialog_content = "Aduh... Seharusnya aku menggunakan bom yang lebih lemah.",
  ui_story_32280401_109_dialog_content = "Hatchi—kita tertutup debu. Lebih baik kita mengibaskannya.",
  ui_story_32280401_110_dialog_content = "Aku juga berharap tinggi...",
  ui_story_32280401_111_dialog_content = "Aku bertanya-tanya kenapa Queen Kandi sangat enggan meninggalkan resep untuk <color=#FFB400>Lemon Supreme</color>-nya?",
  ui_story_32280401_112_dialog_content = "Enak juga, ternyata... *batuk*",
  ui_story_32280401_113_dialog_content = "Ada terlalu banyak debu di sini. Ayo kita pergi saja.",
  ui_story_32280401_114_dialog_content = "Hmm? Kenapa debu ini rasanya aneh?",
  ui_story_32280401_115_dialog_content = "Hah? Ini terlihat seperti garam... Tunggu, itu karena memang ini GARAM!",
  ui_story_32280401_116_dialog_content = "Gua ini pasti merupakan formasi garam alami atau semacamnya.",
  ui_story_32280401_117_dialog_content = "Ada sesuatu yang familiar tentang rasa asin ini juga... Hampir seperti—",
  ui_story_32280401_118_dialog_content = "Seperti rasa permen lemon tertentu?",
  ui_story_32280401_119_dialog_content = "J-Jadi itulah masalahnya! Akhirnya aku paham sekarang!",
  ui_story_32280401_120_dialog_content = "\"Mereka bilang rasa manis paling dihargai saat dipadukan dengan rasa yang berlawanan\"!",
  ui_story_32280401_121_dialog_content = "Garam dari gua ini adalah rahasia di balik rasa manis dan menyegarkan <color=#FFB400>Lemon Supreme</color>!",
  ui_story_32280401_122_dialog_content = "Jadi selama ini, Queen Kandi—",
  ui_story_32280401_123_dialog_content = "Ya! Dia tidak pernah menyembunyikan resep untuk <color=#FFB400>Lemon Supreme</color> sejak awal! Itu karena resepnya ada di tempat ini!",
  ui_story_32280401_124_dialog_content = "Jadi apa gunanya dua catatan itu?",
  ui_story_32280401_125_dialog_content = "Mereka mungkin adalah ide lelucon dari dirinya. Lagipula, Queen Kandi juga dikenal sebagai pengusil yang terkenal.",
  ui_story_32280401_126_dialog_content = "Tak bisa kusangka dia bisa menipu seorang pejuang seperti aku. Dia pasti wanita yang luar biasa.",
  ui_story_32280401_127_option_content = "Jadi, hanya itu yang diperlukan untuk mengubah pikiranmu, ya?",
  ui_story_32280401_128_dialog_content = "Baru saja kamu menyebutnya \"ratu yang curang\"...",
  ui_story_32280401_129_dialog_content = "Oh, itu? Itu hanya kesalahpahaman sederhana, mengingat plot dalam petualangan klasik ini masih berkembang...",
  ui_story_32280401_130_option_content = "Aku benar-benar harus mengakui, Zeta!",
  ui_story_32280401_131_dialog_content = "Jika kamu tidak meledakkan gua itu, kita tidak akan pernah menemukan misteri di balik resep Lemon Supreme.",
  ui_story_32280401_132_dialog_content = "Heheh, akulah protagonis yang ditakdirkan dalam cerita kita, setelah semua.",
  ui_story_32280401_133_dialog_content = "Ini semua ditakdirkan untuk berhasil bagi kita!",
  ui_story_32280401_134_dialog_content = "Dan sekarang setelah kita akhirnya memiliki bahan rahasia di tangan, saatnya pulang! Saya tidak sabar untuk membuat Lemon Supreme dengan kedua tangan saya sendiri!",
  ui_story_32280401_135_dialog_content = "(Meski wajahku masih sangat sakit, melihat Zeta sebahagia ini...)",
  ui_story_32280401_136_dialog_content = "(Itu membuat semuanya sepadan.)"
}
return config
